const items = $input.all();
const returnItems = [];

// Verificar si hay items
if (!items || items.length === 0) {
  return [];
}

for (const item of items) {
  // Verificar que el item tenga la estructura correcta
  if (!item || !item.json || !item.json.start || !item.json.start.dateTime) {
    continue; // Saltar este item si no tiene la estructura correcta
  }

  let data = item.json;

  const dia = data.start.dateTime.split('T')[0];
  const inicio = data.start.dateTime.split('T')[1].substring(0, 5);
  const final = data.end.dateTime.split('T')[1].substring(0, 5);

  returnItems.push({
    json: {
      dia: dia,
      inicio: inicio, 
      final: final
    }
  });
}

return returnItems;

function calcularTurnosDisponibles() {
  const tiempoData = $('When Executed by Another Workflow').first().json;
  const tallerData = $('Get row(s) in sheet1').first().json;
  const feriadosData = $('feriados').first().json.feriadosEncontrados || [];
  const turnosOcupadosRaw = $('Code').all();

  let tiempoMantenimiento = 30;
  if (tiempoData && tiempoData.query) {
    try {
      const queryVal = typeof tiempoData.query === "string" ? tiempoData.query : JSON.stringify(tiempoData.query);
      const parsed = JSON.parse(queryVal);
      if (parsed?.tiempo) {
        if (parsed.tiempo.includes(":")) {
          const [h, m] = parsed.tiempo.split(":").map(Number);
          tiempoMantenimiento = h * 60 + m;
        } else tiempoMantenimiento = parseInt(parsed.tiempo);
      }
    } catch {
      tiempoMantenimiento = 30;
    }
  }

  const tiempoRecepcion = parseInt(tallerData.Recepcion || 0);
  const tiempoLavado = parseInt(tallerData.Lavado || 0);
  const tiempoEntrega = parseInt(tallerData.Entrega || 0);

  // Tiempo TOTAL que se le muestra al usuario (incluye recepción, lavado y entrega)
  const tiempoTotal = Math.max(tiempoMantenimiento + tiempoRecepcion + tiempoLavado + tiempoEntrega - 15, 15);

  function timeToMinutes(t) { const [h, m] = t.split(':').map(Number); return h * 60 + m; }
  function minutesToTime(min) {
    const h = Math.floor(min / 60), m = min % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
  }

  function formatoFecha(fechaStr) {
    const dias = ["Domingo","Lunes","Martes","Miércoles","Jueves","Viernes","Sábado"];
    const fecha = new Date(fechaStr);
    const diaSemana = dias[fecha.getDay()];
    const dd = fecha.getDate().toString().padStart(2, '0');
    const mm = (fecha.getMonth() + 1).toString().padStart(2, '0');
    const yyyy = fecha.getFullYear();
    return `${diaSemana} ${dd}/${mm}/${yyyy}`;
  }

  const turnosOcupados = [];
  turnosOcupadosRaw.forEach(item => {
    if (item.json && Array.isArray(item.json)) turnosOcupados.push(...item.json);
    else if (item.json && item.json.dia) turnosOcupados.push(item.json);
  });

  const fechasOcupadas = new Set();
  turnosOcupados.forEach(t => {
    if (t.dia && t.inicio && t.final) {
      const ini = timeToMinutes(t.inicio), fin = timeToMinutes(t.final);
      for (let m = ini; m < fin; m += 15) fechasOcupadas.add(`${t.dia}_${minutesToTime(m)}`);
    }
  });

  const apertura = timeToMinutes(tallerData.Apertura);
  const cierre = timeToMinutes(tallerData.Cierre);
  const iniAlm = timeToMinutes(tallerData["Inicio Almuerzo"]);
  const finAlm = timeToMinutes(tallerData["Fin Almuerzo"]);
  const iniDes = timeToMinutes(tallerData["Inicio Desayuno"]);
  const finDes = timeToMinutes(tallerData["Fin Desayuno"]);

  const feriados = new Set(feriadosData);
  const turnosDisponibles = [];

  const hoy = new Date();
  const hoyStr =
      hoy.getFullYear() + '-' +
      String(hoy.getMonth() + 1).padStart(2, '0') + '-' +
      String(hoy.getDate()).padStart(2, '0');
  const minutosAhora = hoy.getHours() * 60 + hoy.getMinutes();

  let fecha = new Date(hoy);
  fecha.setHours(0, 0, 0, 0);

  while (turnosDisponibles.length < 6) {
    const fechaStr =
        fecha.getFullYear() + '-' +
        String(fecha.getMonth() + 1).padStart(2, '0') + '-' +
        String(fecha.getDate()).padStart(2, '0');

    const diaSemana = fecha.getDay();

    if (diaSemana >= 1 && diaSemana <= 5 && !feriados.has(fechaStr)) {
      const turnosDia = [];

      const estaDisponible = (inicio, duracion) => {
        const fin = inicio + duracion;
        if (inicio < finAlm && fin > iniAlm) return false;
        if (inicio < finDes && fin > iniDes) return false;
        for (let m = inicio; m < fin; m += 15) {
          if (fechasOcupadas.has(`${fechaStr}_${minutesToTime(m)}`)) return false;
        }
        return true;
      };

      // El bloque que debe caber "libre" hasta cierre sigue siendo el tiempoTotal,
      // para no ofrecer turnos que se pasen del horario de cierre.
      for (let m = apertura; m + tiempoTotal <= cierre; m += 15) {

        const inicioTurno = m - tiempoRecepcion;
        if (fechaStr === hoyStr && inicioTurno <= minutosAhora) continue;

        // CAMBIO: la validación contra el calendario (turnos ocupados + almuerzo/desayuno)
        // se hace solo con tiempoMantenimiento, no con tiempoTotal.
        if (estaDisponible(m, tiempoMantenimiento)) {
          turnosDia.push({
            dia: fechaStr,
            inicio: minutesToTime(m - tiempoRecepcion), // se muestra incluyendo recepción
            final: minutesToTime(m + tiempoTotal),       // se muestra incluyendo lavado/entrega
            Id_Calendario: tallerData.Id_Calendario,
            fechaFormato: formatoFecha(fechaStr)
          });
        }
      }

      turnosDisponibles.push(...turnosDia.slice(0, 2));
    }

    fecha.setDate(fecha.getDate() + 1);
    if (turnosDisponibles.length >= 6) break;
  }

  turnosDisponibles.sort((a, b) =>
    a.dia === b.dia ? a.inicio.localeCompare(b.inicio) : new Date(a.dia) - new Date(b.dia)
  );

  return {
    turnosDisponibles: turnosDisponibles.slice(0, 6),
    tiempoMantenimientoCalculado: tiempoTotal
  };
}

const resultado = calcularTurnosDisponibles();

return [{
  json: {
    turnosDisponibles: resultado.turnosDisponibles,
    tiempoTotalCalculado: resultado.tiempoMantenimientoCalculado,
    cantidadTurnos: resultado.turnosDisponibles.length
  }
}];

function obtenerFeriados() {
  const feriadosData = $input.all();
  const feriados = [];

  // Fechas que NO queremos incluir aunque vengan como "Día festivo"
  const fechasExcluidas = ["2026-07-10"];

  feriadosData.forEach(item => {
    // Solo procesar si la descripción es "Día festivo"
    if (!item.json || item.json.description !== "Día festivo") return;
    if (item.json.start && item.json.start.date) {
      feriados.push(item.json.start.date);
    }
    if (item.json.end && item.json.end.date && item.json.start.date !== item.json.end.date) {
      const fechaInicio = new Date(item.json.start.date);
      const fechaFin = new Date(item.json.end.date);

      const fechaActual = new Date(fechaInicio);
      while (fechaActual < fechaFin) {
        feriados.push(fechaActual.toISOString().split('T')[0]);
        fechaActual.setDate(fechaActual.getDate() + 1);
      }
    }
  });

  const feriadosUnicos = [...new Set(feriados)]
    .filter(fecha => !fechasExcluidas.includes(fecha))
    .sort();

  return feriadosUnicos;
}

const feriadosEncontrados = obtenerFeriados();
return [{
  json: {
    feriadosEncontrados: feriadosEncontrados
  }
}];

